-- Migration 280: MD 2026 Legislative Race Scaffold - Phase 96 Plan 02
-- Generated by generate_md_legislative_races.ps1
-- 47 Senate districts + 71 House districts = 118 race rows, general election only
--
-- ROADMAP DEVIATION: ROADMAP estimated 198 total race rows (one-row-per-seat model).
-- Actual count is 130 (12 statewide + 47 senate + 71 SLDL house geofences).
-- The reduction is enforced by UNIQUE (election_id, position_name, primary_party)
-- which makes one-row-per-district the only viable model per D-01.
-- ROADMAP 'cron_active=true' language is also stale -- no such column exists on
-- essentials.discovery_jurisdictions; eligibility is date-based (180-day cron window).

DO $$
DECLARE
  v_general_id UUID;
BEGIN
  SELECT id INTO v_general_id FROM essentials.elections
  WHERE name = '2026 Maryland General Election' AND state = 'MD';

  INSERT INTO essentials.races (election_id, office_id, position_name, primary_party, seats)
  VALUES (v_general_id,
    (SELECT o.id FROM essentials.offices o
     JOIN essentials.districts d ON d.id = o.district_id
     JOIN essentials.chambers ch ON ch.id = o.chamber_id
     WHERE d.geo_id = '24001' AND d.district_type = 'STATE_UPPER' AND d.state = 'md'
       AND ch.name = 'Maryland Senate' LIMIT 1),
    'MD State Senate District 1', NULL, 1)
  ON CONFLICT (election_id, position_name) WHERE primary_party IS NULL DO NOTHING;
END $$;
